"""Pipeline checkpoints for resume-after-ASR (skip expensive re-transcription)."""

from __future__ import annotations

import json
import logging
import time
from pathlib import Path
from typing import Any

_log = logging.getLogger("transub_engine.checkpoint")

# Stages that can be resumed from
STAGE_ASR_DONE = "asr_done"
STAGE_MT_DONE = "mt_done"


def _ckpt_path(job_id: str) -> Path:
    from .paths import get_jobs_root

    safe = "".join(ch for ch in str(job_id) if ch.isalnum() or ch in "-_")[:64]
    return get_jobs_root() / f"{safe}.ckpt.json"


def save_checkpoint(
    job_id: str,
    *,
    stage: str,
    request: dict[str, Any] | None,
    source_cues: list[dict[str, Any]] | None = None,
    zh_cues: list[dict[str, Any]] | None = None,
    extra: dict[str, Any] | None = None,
) -> Path | None:
    if not job_id:
        return None
    try:
        payload: dict[str, Any] = {
            "id": job_id,
            "stage": stage,
            "savedAt": time.time(),
            "request": _safe_request(request),
            "sourceCues": list(source_cues or []),
            "zhCues": list(zh_cues or []) if zh_cues is not None else None,
            "extra": dict(extra or {}),
        }
        path = _ckpt_path(job_id)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(payload, ensure_ascii=False), encoding="utf-8")
        return path
    except Exception as err:
        _log.warning("save_checkpoint failed: %s", err)
        return None


def load_checkpoint(job_id: str) -> dict[str, Any] | None:
    path = _ckpt_path(job_id)
    if not path.is_file():
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else None
    except Exception as err:
        _log.warning("load_checkpoint failed: %s", err)
        return None


def delete_checkpoint(job_id: str) -> None:
    try:
        path = _ckpt_path(job_id)
        if path.is_file():
            path.unlink()
    except Exception:
        pass


def build_resume_request(checkpoint: dict[str, Any]) -> dict[str, Any]:
    """Merge checkpoint into a new job request that skips ASR when possible."""
    req = dict(checkpoint.get("request") or {})
    stage = str(checkpoint.get("stage") or "")
    req["_checkpoint"] = {
        "stage": stage,
        "sourceCues": checkpoint.get("sourceCues") or [],
        "zhCues": checkpoint.get("zhCues"),
        "resumeFromId": checkpoint.get("id"),
        "extra": checkpoint.get("extra") or {},
    }
    return req


def _safe_request(req: Any) -> dict[str, Any]:
    if not isinstance(req, dict):
        return {}
    keep = (
        "task",
        "mediaPath",
        "outputDir",
        "language",
        "asrModel",
        "mtModel",
        "subFormats",
        "device",
        "vad",
        "audio",
        "glossary",
        "beamSize",
        "ffmpegPath",
    )
    return {k: req[k] for k in keep if k in req}
